	@Test
	void bulkImportUsesBoundedBatchesWithoutMaterializingContexts() throws Exception {
		SailStore store = mock(SailStore.class);
		SailSource source = mock(SailSource.class);
		SailSink sink = mock(SailSink.class);
		when(store.getExplicitSailSource()).thenReturn(source);
		when(source.sink(IsolationLevels.NONE)).thenReturn(sink);

		NoMaterializeModel bulk = new NoMaterializeModel();
		bulk.setNamespace("ex", "urn:example:");
		var vf = SimpleValueFactory.getInstance();
		for (int i = 0; i < 2050; i++) {
			bulk.add(vf.createStatement(vf.createIRI("urn:subject:" + i), vf.createIRI("urn:predicate"),
					vf.createLiteral("value:" + i), vf.createIRI("urn:context:" + (i % 4))));
		}

		Set<Statement> approved = new java.util.HashSet<>();
		AtomicInteger largestBatch = new AtomicInteger();
		doAnswer(invocation -> recordBatch(invocation, approved, largestBatch))
				.when(sink)
				.approveAll(anySet(), anySet());

		new SailSourceModel(store, bulk);

		assertThat(approved).hasSize(2050);
		assertThat(largestBatch.get()).isLessThanOrEqualTo(IMPORT_BATCH_SIZE);
		verify(sink).setNamespace("ex", "urn:example:");
		verify(sink).flush();
	}

	@Test
	void failedBulkImportClosesItsCursorAndSink() throws Exception {
		SailStore store = mock(SailStore.class);
		SailSource source = mock(SailSource.class);
		SailSink sink = mock(SailSink.class);
		when(store.getExplicitSailSource()).thenReturn(source);
		when(source.sink(IsolationLevels.NONE)).thenReturn(sink);

		TrackingBulkModel bulk = new TrackingBulkModel();
		bulk.add(SimpleValueFactory.getInstance()
				.createStatement(
						SimpleValueFactory.getInstance().createIRI("urn:subject"),
						SimpleValueFactory.getInstance().createIRI("urn:predicate"),
						SimpleValueFactory.getInstance().createLiteral("value"), CONTEXT));
		doAnswer(invocation -> {
			Iterator<Statement> iterator = statements(invocation).iterator();
			if (iterator.hasNext()) {
				iterator.next();
			}
			throw new SailException("simulated import failure");
		}).when(sink).approveAll(anySet(), anySet());

		assertThatThrownBy(() -> new SailSourceModel(store, bulk))
				.isInstanceOf(SailException.class)
				.hasMessage("simulated import failure");

		assertThat(bulk.lastIterator).isNotNull();
		assertThat(bulk.lastIterator.closeCount).isEqualTo(1);
		verify(sink).close();
	}

